    const render = () => { const portals=new Map(); for(const item of state.items){const key=item.siteSigla||'SEM PORTAL';if(!portals.has(key))portals.set(key,new Map());const campaigns=portals.get(key);const campaignKey=item.campanhaId||('i-'+item.id);if(!campaigns.has(campaignKey))campaigns.set(campaignKey,{item,insertions:[]});campaigns.get(campaignKey).insertions.push(item)} const html=[...portals].map(([portal,campaigns])=>{const groups=[...campaigns.values()];const all=groups.flatMap(group=>group.insertions);const first=groups[0]?.item;const logo=siteLogoUrl(first||{});const count=(stateName)=>all.filter(item=>(item.publicationStates||[]).includes(stateName)||(item.evidenceStates||[]).includes(stateName)).length;return '<section class="portal"><header class="portal-head"><div class="brand">'+(logo?'<img src="'+escapeHtml(logo)+'" alt="'+escapeHtml(portal)+'" loading="lazy">':'<span>'+escapeHtml(portal)+'</span>')+'<div><h2>'+escapeHtml(first?.siteNome||portal)+'</h2><span>'+escapeHtml(safeUrl(first?.portalUrl)?new URL(first.portalUrl).hostname:portal)+'</span></div></div><div class="portal-stats"><span><b>'+count('active')+'</b> ativas</span><span><b>'+count('scheduled')+'</b> agendadas</span><span><b>'+count('ended')+'</b> encerradas</span><span><b>'+count('complete')+'</b> em dia</span><span><b>'+count('missing')+'</b> pendentes</span><span><b>'+count('invalid')+'</b> com erro</span><span><b>'+count('not_published')+'</b> sem publicação</span></div></header>'+groups.map(({item,insertions})=>{const days=insertions.flatMap(i=>i.evidenceDays||[]);const approved=days.filter(day=>day.status.startsWith('audited')).length;return '<article class="campaign"><header class="campaign-head"><div><h3>'+escapeHtml(item.campanhaName||('Campanha '+item.campanhaId))+'</h3><p class="campaign-meta">'+escapeHtml(item.clienteNome||'Cliente não informado')+' · '+escapeHtml(item.agenciaNome||'Agência não informada')+' · '+escapeHtml(item.piCodigo||'PI não informada')+'</p><div class="campaign-downloads"><button class="button campaign-package" type="button" data-pi="'+escapeHtml(item.piCodigo||'')+'" data-site="'+escapeHtml(portal)+'" '+(!item.piCodigo?'disabled title="PI não informada"':'')+'>'+icon('image')+' Baixar ZIP desta campanha</button></div></div><div class="campaign-summary"><span>'+insertions.length+' '+(insertions.length===1?'inserção':'inserções')+'</span><span>'+approved+' de '+days.length+' prints aprovados</span><strong>'+((insertions.some(i=>(i.evidenceStates||[]).includes('missing')))?'Há prints pendentes':'Todas as inserções estão em dia')+'</strong></div></header><div class="insertions">'+insertions.map(insertionMarkup).join('')+'</div></article>'}).join('')+'</section>'}).join(''); byId('reportContent').innerHTML=html||'<div class="empty">Nenhuma campanha encontrada para estes filtros.</div>'; bindDynamicActions(); };
    const openAdrotateAd = async (button) => { button.disabled=true;button.textContent='Localizando anúncio…';try{const response=await fetch(REPORT_API_BASE+'/api/integrations/adrotate/insertions/'+encodeURIComponent(button.dataset.insertion)+'/relation',{credentials:'include'});if(!response.ok)throw new Error('API respondeu HTTP '+response.status);const relation=await response.json();const url=safeUrl(relation.exactLiveMatches?.[0]?.adminEditUrl||relation.historicalAdminMatches?.[0]?.adminEditUrl);if(!url)throw new Error('Anúncio não localizado no AdRotate');const link=document.createElement('a');link.className='button';link.href=url;link.target='_blank';link.rel='noopener';link.textContent='Abrir anúncio no AdRotate';button.replaceWith(link);link.click()}catch(error){button.disabled=false;button.textContent='Tentar abrir anúncio novamente';byId('statusMessage').className='wrap notice bad';byId('statusMessage').textContent=error.message} };
    const bindDynamicActions = () => { document.querySelectorAll('.media-open').forEach((button)=>button.addEventListener('click',()=>openMedia(Number(button.dataset.insertion)))); document.querySelectorAll('.adrotate-ad-open').forEach((button)=>button.addEventListener('click',()=>openAdrotateAd(button))); document.querySelectorAll('.evidence-day').forEach((button)=>button.addEventListener('click',()=>openEvidence(Number(button.dataset.insertion),Number(button.dataset.day)))); document.querySelectorAll('.campaign-package').forEach((button)=>button.addEventListener('click',()=>preparePackage(button))); const observer=new IntersectionObserver((entries)=>entries.forEach(({isIntersecting,target})=>{if(isIntersecting&&target.dataset.src){target.src=target.dataset.src;delete target.dataset.src;observer.unobserve(target)}}),{rootMargin:'120px'});document.querySelectorAll('.thumb img[data-src]').forEach((image)=>observer.observe(image)); };
    const openMedia = (id) => { const item=state.items.find((entry)=>entry.id===id);const url=safeUrl(item?.mediaUrl);if(!url)return;byId('mediaTitle').textContent=(item.campanhaName||'Campanha')+' · Inserção #'+item.id;byId('mediaMeta').textContent=(item.siteSigla||'Portal')+' · '+(item.localFormatoNormalizado||item.localFormato||'Formato não informado');byId('mediaOriginal').href=url;const video=/[.]mp4(?:[?#]|$)/i.test(url);byId('mediaImage').hidden=video;byId('mediaVideo').hidden=!video;if(video){byId('mediaVideo').src=url}else{byId('mediaImage').src=url;byId('mediaImage').alt='Mídia de '+(item.campanhaName||'campanha')}byId('mediaModal').showModal(); };
