    const showEvidenceProgress=(label,percent=0,bad=false,support='')=>{const value=Math.max(0,Math.min(100,Number.isFinite(percent)?Math.round(percent):0));const box=byId('evidenceJobProgress');box.hidden=false;box.className='notice'+(bad?' bad':'');box.innerHTML='<div class="job-progress" role="progressbar" aria-valuenow="'+value+'" aria-valuemin="0" aria-valuemax="100" aria-label="Progresso da geração do print"><i style="width:'+value+'%"></i></div><div class="job-progress-copy"><strong>'+escapeHtml(label)+'</strong><span>'+value+'%</span></div>'+(support?'<small>'+escapeHtml(support)+'</small>':'');};
    const waitForEvidenceJob=async(item,day,jobId)=>{if(state.evidencePollJobId===jobId)return;state.evidencePollJobId=jobId;let missing=0;try{for(let attempt=0;attempt<300;attempt++){const response=await fetch(REPORT_API_BASE+'/api/insertions/'+item.id+'/capture-proof/jobs/'+encodeURIComponent(jobId),{credentials:'include',headers:{accept:'application/json'}});if(response.status===404&&missing++<3){await new Promise(resolve=>setTimeout(resolve,1000));continue}if(!response.ok)throw new Error('Não foi possível consultar o andamento. Tente novamente.');const job=await response.json();const progress=job.progress||{};showEvidenceProgress(stageLabels[progress.stage]||progress.message||'Gerando print',progress.percent);if(job.status==='completed'){writeActiveJob(null);await load();const fresh=state.items.find(entry=>entry.id===item.id);const index=[...(fresh?.evidenceDays||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date))).findIndex(entry=>entry.date===day.date);if(fresh&&index>=0)openEvidence(item.id,index);showEvidenceProgress(stageLabels.completed,100);return}if(job.status==='failed'){const support=[job.support?.message,job.support?.code].filter(Boolean).join(' Código: ');showEvidenceProgress(stageLabels.failed,progress.percent,true,support);byId('evidenceLinks').insertAdjacentHTML('afterbegin','<button class="button primary" id="retryEvidence" type="button">Tentar novamente</button>');byId('retryEvidence').addEventListener('click',()=>generateSelectedEvidence(true));return}await new Promise(resolve=>setTimeout(resolve,2000))}throw new Error('A geração demorou mais que o esperado. Tente consultar novamente.')}catch(error){showEvidenceProgress(error.message,0,true)}finally{state.evidencePollJobId=null}};
    const generateSelectedEvidence=async(retry=false)=>{const item=state.evidenceItem;const day=state.evidenceDays[state.evidenceIndex];if(!item||!day||state.evidencePollJobId)return;const previous=readActiveJob();const attempt=retry?Number(previous?.attempt||0)+1:Number(previous?.attempt||0);showEvidenceProgress('Solicitação recebida',0);try{const response=await fetch(REPORT_API_BASE+'/api/insertions/'+item.id+'/capture-proof/jobs',{method:'POST',credentials:'include',headers:{'content-type':'application/json','idempotency-key':['report',item.id,day.date,'manual',attempt].join(':')},body:JSON.stringify({date:day.date,candidate:true,promote:true,reconstructionReason:'late_publication_recovery'})});if(!response.ok)throw new Error('Não foi possível solicitar o print. Tente novamente.');const created=await response.json();writeActiveJob({insertionId:item.id,date:day.date,jobId:created.jobId,attempt});await waitForEvidenceJob(item,day,created.jobId)}catch(error){showEvidenceProgress(error.message,0,true)}};
    const deleteSelectedEvidence = async () => { const day=state.evidenceDays[state.evidenceIndex];if(!day?.evidenceId||!confirm('Excluir esta evidência? A data voltará para a fila noturna de regeneração.'))return;showEvidenceProgress('Excluindo evidência');try{const response=await fetch(REPORT_API_BASE+'/api/evidences/'+day.evidenceId,{method:'DELETE',credentials:'include'});if(!response.ok)throw new Error('API respondeu HTTP '+response.status);byId('evidenceModal').close();await load()}catch(error){showEvidenceProgress('Falha: '+error.message,null,true)} };
